WITH flattened_attrs AS (SELECT id, tier_prices, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT CASE WHEN lowest_price >= 26 THEN 'HIGH' ELSE 'LOW' END AS lowest_price_tier, CASE WHEN entry_price >= 25 THEN 'HIGH' ELSE 'LOW' END AS entry_price_tier, ROUND(AVG(entry_price), 2) AS avg_entry_price, APPROX_PERCENTILE(lowest_price, ARRAY(0.25, 0.5, 0.75)) AS lowest_price_quartiles, PERCENTILE_APPROX(lowest_price, 0.95) AS lowest_price_p95, DENSE_RANK() OVER (PARTITION BY CASE WHEN lowest_price >= 26 THEN 'HIGH' ELSE 'LOW' END ORDER BY ROUND(AVG(entry_price), 2) DESC) AS avg_entry_price_dense_rank FROM flattened_attrs GROUP BY CASE WHEN lowest_price >= 26 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN entry_price >= 25 THEN 'HIGH' ELSE 'LOW' END HAVING PERCENTILE_APPROX(lowest_price, 0.95) < 1000000 ORDER BY entry_price_tier
